.darma-loader-darma-b7-radar-sweep { --accent: var(--loader-color, #10b981); --accent-2: var(--loader-secondary-color, #065f46); width: var(--loader-size, 76px); height: var(--loader-size, 76px); border-radius: 50%; border: calc(var(--loader-size, 76px) * .03) solid color-mix(in srgb, var(--accent-2) 40%, transparent); position: relative; overflow: hidden; }
.darma-loader-darma-b7-radar-sweep::before { content: ''; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, transparent 0deg, color-mix(in srgb, var(--accent) 65%, transparent) 55deg, transparent 70deg); animation: darma-loader-darma-b7-radar-sweep-radar calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b7-radar-sweep::after { content: ''; position: absolute; left: 50%; top: 50%; width: 9%; height: 9%; margin: -4.5% 0 0 -4.5%; border-radius: 50%; background: var(--accent); }
@keyframes darma-loader-darma-b7-radar-sweep-radar { to { transform: rotate(360deg); } }

